import FeatureSectionV8 from "./components/feature-section-v8"

export default function Page() {
  return <FeatureSectionV8 />
}

"use client"

import { featureColumns } from "../lib/config"
import FeatureCard from "./feature-card"
import { useInViewOnce } from "../hooks/use-in-view-once"

export default function FeatureGrid() {
  const { ref, active } = useInViewOnce(0.2)

  return (
    <div ref={ref} className="mx-auto max-w-5xl border border-border">
      <ul className="m-0 grid list-none grid-cols-1 p-0 md:grid-cols-2 lg:grid-cols-[2fr_3fr]">
        {featureColumns.slice(0, 2).map((column, index) => (
          <FeatureCard key={column.id} column={column} index={index} live={active} />
        ))}
      </ul>
      <ul className="m-0 grid list-none grid-cols-1 border-t border-border p-0 md:grid-cols-2 lg:grid-cols-[2fr_3fr]">
        {featureColumns.slice(2).map((column, index) => (
          <FeatureCard
            key={column.id}
            column={column}
            index={index}
            live={active}
            className="-mt-px"
          />
        ))}
      </ul>
    </div>
  )
}

import { cn } from "@/lib/utils"

import type { FeatureColumn } from "../lib/config"
import { featurePreviewMinHeights } from "../lib/config"
import FeaturePreviewSlot from "./feature-preview-slot"

export default function FeatureCard({
  column,
  index,
  className,
  live = false,
  subgrid = false,
}: {
  column: FeatureColumn
  index: number
  className?: string
  live?: boolean
  subgrid?: boolean
}) {
  const reversed = column.layout === "reversed"
  const previewSize = column.previewSize ?? "default"
  const previewMinHeight = featurePreviewMinHeights[previewSize]
  const swapAt = subgrid ? "md" : "lg"

  return (
    <li
      className={cn(
        "grid min-w-0 grid-rows-[auto_auto] border border-border",
        subgrid && "md:row-span-2 md:grid-rows-subgrid",
        index > 0 && "md:-ml-px",
        className
      )}
    >
      <div
        className={cn(
          "relative flex h-full min-h-0 flex-col border-border",
          previewMinHeight,
          reversed &&
            (swapAt === "md"
              ? "max-md:border-b md:row-start-2 md:border-t md:border-b-0"
              : "max-lg:border-b lg:row-start-2 lg:border-t lg:border-b-0"),
          !reversed && "border-b"
        )}
      >
        <FeaturePreviewSlot
          id={column.id}
          title={column.title}
          description={column.description}
          live={live}
          previewSize={previewSize}
        />
      </div>
      <div
        className={cn(
          "p-4 sm:p-5",
          reversed &&
            (swapAt === "md" ? "md:row-start-1" : "lg:row-start-1")
        )}
      >
        <h3 className="m-0 text-base font-medium tracking-[-0.02em] text-foreground sm:text-lg">
          {column.title}
        </h3>
        <p className="m-0 mt-2 text-[0.875rem] leading-[1.6] text-muted-foreground">
          {column.description}
        </p>
      </div>
    </li>
  )
}

"use client"

import { cn } from "@/lib/utils"

import { buildFeaturePreview } from "../lib/build-feature-preview"
import ProductPreviewFeature from "./product-preview-feature"
import { featurePreviewMinHeights, type FeaturePreviewSize } from "../lib/config"

import "../styles/feature-section-v8.css"

export default function FeaturePreviewSlot({
  id,
  title,
  description,
  live = false,
  previewSize = "default",
  className,
}: {
  id: string
  title: string
  description: string
  live?: boolean
  previewSize?: FeaturePreviewSize
  className?: string
}) {
  const spec = buildFeaturePreview({ id, title, description, size: "mini" })

  return (
    <div
      className={cn(
        "fsv8-dot-pattern relative h-full min-h-0 overflow-hidden",
        featurePreviewMinHeights[previewSize],
        className
      )}
    >
      <div className="absolute inset-0 flex min-w-0 items-stretch p-4 sm:p-5">
        <ProductPreviewFeature
          className="min-h-0 min-w-0 flex-1"
          spec={spec}
          title={title}
          description={description}
          instanceId={id}
          live={live}
        />
      </div>
    </div>
  )
}

"use client"

import type { CSSProperties, ReactNode } from "react"

import { cn } from "@/lib/utils"

import { elementDelay, elementDuration } from "../lib/animation-timing"
import MetricCard from "./metric-card"
import { useLiveFeaturePreview } from "../hooks/use-live-feature-preview"

import type { FeaturePreviewSpec, MiniAppScreenZone } from "../lib/build-feature-preview"

function MockScreen({ children }: { children: ReactNode }) {
  return (
    <div className="fsv8-mock-screen fsv8-mock-body flex min-h-0 flex-1 flex-col">
      {children}
    </div>
  )
}

function chartValues(chart: { heights?: ReadonlyArray<number>; points?: ReadonlyArray<number> }) {
  return chart.heights ?? chart.points ?? []
}

function MiniAreaChart({ points }: { points: ReadonlyArray<number> }) {
  if (points.length < 2) return null

  const width = 100
  const height = 100
  const step = width / (points.length - 1)
  const linePath = points
    .map((point, index) => {
      const x = index * step
      const y = height - (point / 100) * height
      return `${index === 0 ? "M" : "L"} ${x.toFixed(2)} ${y.toFixed(2)}`
    })
    .join(" ")
  const areaPath = `${linePath} L ${width} ${height} L 0 ${height} Z`

  return (
    <svg
      className="fsv8-area-chart block h-full w-full"
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      aria-hidden
    >
      <path d={areaPath} fill="var(--pp-accent-muted)" />
      <path
        d={linePath}
        fill="none"
        stroke="var(--pp-accent)"
        strokeWidth="1.5"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  )
}

function MiniLineChart({ points }: { points: ReadonlyArray<number> }) {
  if (points.length < 2) return null

  const width = 100
  const height = 100
  const step = width / (points.length - 1)
  const path = points
    .map((point, index) => {
      const x = index * step
      const y = height - (point / 100) * height
      return `${index === 0 ? "M" : "L"} ${x.toFixed(2)} ${y.toFixed(2)}`
    })
    .join(" ")

  return (
    <svg
      className="fsv8-line-chart block h-full w-full"
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      aria-hidden
    >
      <path
        d={path}
        fill="none"
        stroke="var(--pp-accent)"
        strokeWidth="1.75"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  )
}

function MiniBarChart({
  heights,
  thin = false,
  live = false,
  scan,
  seed = "bars",
}: {
  heights: ReadonlyArray<number>
  thin?: boolean
  live?: boolean
  scan?: boolean
  seed?: string
}) {
  const maxIndex = heights.reduce(
    (best, height, index) => (height > heights[best] ? index : best),
    0
  )
  const showScan = scan ?? live

  return (
    <div
      className={cn(
        thin
          ? "fsv8-bar-chart fsv8-bar-chart--thin flex min-h-0 flex-1 items-end justify-between px-2.5 py-2"
          : "fsv8-bar-chart flex min-h-0 flex-1 items-end gap-1 px-2.5 py-2",
        showScan && "fsv8-bar-chart-live"
      )}
      style={
        showScan
          ? ({
              "--fsv8-scan-delay": `${elementDelay(`${seed}-scan`, 0, 4800)}ms`,
            } as CSSProperties)
          : undefined
      }
      aria-hidden
    >
      {heights.map((height, index) => (
        <div
          key={index}
          className={cn(
            thin
              ? "fsv8-bar fsv8-bar--thin shrink-0"
              : "fsv8-bar w-1.5 shrink-0",
            live && "fsv8-bar-live",
            index === maxIndex ? "bg-(--pp-accent)" : "bg-(--pp-accent-muted)"
          )}
          style={
            live
              ? ({
                  height: `${height}%`,
                  "--fsv8-bar-delay": `${elementDelay(`${seed}-bar-${index}`, 0, 720)}ms`,
                  "--fsv8-bar-duration": `${elementDuration(`${seed}-bar-d-${index}`, 380, 1100)}ms`,
                  "--fsv8-bar-rise-delay": `${elementDelay(`${seed}-bar-rise-${index}`, 0, 640)}ms`,
                  "--fsv8-bar-rise-duration": `${elementDuration(`${seed}-bar-rise-d-${index}`, 420, 980)}ms`,
                } as CSSProperties)
              : { height: `${height}%` }
          }
        />
      ))}
    </div>
  )
}

function DotGridPanel({
  dotGrid,
  compact = false,
  live = false,
  seed = "dots",
}: {
  dotGrid: ReadonlyArray<ReadonlyArray<boolean>>
  compact?: boolean
  live?: boolean
  seed?: string
}) {
  const rows = dotGrid.length
  const cols = dotGrid[0]?.length ?? 1

  return (
    <div
      className={cn(
        compact ? "fsv8-dot-grid fsv8-dot-grid--compact" : "fsv8-dot-grid",
        live && "fsv8-dot-grid-live"
      )}
      style={{
        gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
        gridTemplateRows: `repeat(${rows}, minmax(0, 1fr))`,
      }}
      aria-hidden
    >
      {dotGrid.flatMap((row, rowIndex) =>
        row.map((active, colIndex) => (
          <div key={`${rowIndex}-${colIndex}`} className="fsv8-dot-grid-cell">
            <span
              className={cn(
                "fsv8-dot-grid-dot",
                active && "fsv8-dot-grid-dot--active",
                live && active && "fsv8-dot-grid-dot--live"
              )}
              style={
                live && active
                  ? ({
                      "--fsv8-dot-delay": `${elementDelay(`${seed}-dot-${rowIndex}-${colIndex}`, 0, 2200)}ms`,
                      "--fsv8-dot-duration": `${elementDuration(`${seed}-dot-d-${rowIndex}-${colIndex}`, 1200, 2800)}ms`,
                    } as CSSProperties)
                  : undefined
              }
            />
          </div>
        ))
      )}
    </div>
  )
}

function LiveStreamZone({
  zone,
  live,
  instanceId,
}: {
  zone: Extract<MiniAppScreenZone, { type: "live-stream" }>
  live: boolean
  pulseKey: number
  instanceId: string
}) {
  return (
    <MockScreen>
      <div className="fsv8-stat-strip flex shrink-0 border-b border-(--pp-border)">
        {zone.stats.map((stat) => (
          <div
            key={stat.label}
            className="fsv8-stat-strip-item flex flex-1 flex-col gap-0.5 px-2.5 py-2"
          >
            <span className="text-base font-medium tracking-tight text-foreground tabular-nums">
              {stat.value}
            </span>
            <span className="font-mono text-[0.625rem] uppercase tracking-wider text-muted-foreground">
              {stat.label}
            </span>
          </div>
        ))}
      </div>
      <MiniBarChart heights={zone.bars} thin live={live} scan={false} seed={`${instanceId}-stream`} />
    </MockScreen>
  )
}

function SignalFlowZone({
  zone,
  live,
  activeNodeIndex,
  instanceId,
}: {
  zone: Extract<MiniAppScreenZone, { type: "signal-flow" }>
  live: boolean
  pulseKey: number
  activeNodeIndex: number
  instanceId: string
}) {
  return (
    <MockScreen>
      <div
        className={cn(
          "fsv8-signal-route shrink-0 border-b border-(--pp-border) px-3 py-3",
          live && "fsv8-signal-route-live"
        )}
      >
        <div className="flex items-end">
          {zone.nodes.map((node, index) => {
            const isActive = live && index === activeNodeIndex
            const isPast = live && index < activeNodeIndex

            return (
              <div key={node.label} className="flex min-w-0 flex-1 items-end">
                <div className="flex min-w-0 flex-1 flex-col gap-1.5">
                  <div className="flex min-w-0 items-baseline justify-between gap-2">
                    <span
                      className={cn(
                        "truncate font-mono text-[0.625rem] leading-none",
                        isActive ? "text-foreground" : "text-muted-foreground"
                      )}
                    >
                      {node.label}
                    </span>
                    <span
                      className={cn(
                        "shrink-0 font-mono text-[0.5625rem] tabular-nums leading-none",
                        isActive ? "text-foreground/70" : "text-muted-foreground/55"
                      )}
                    >
                      {node.volume}
                    </span>
                  </div>
                  <div
                    className={cn(
                      "fsv8-signal-hop h-1 w-full",
                      isActive && "fsv8-signal-hop--active",
                      isPast && "fsv8-signal-hop--past"
                    )}
                  />
                </div>
                {index < zone.nodes.length - 1 ? (
                  <span
                    className={cn(
                      "fsv8-signal-gap mb-0.5 h-px w-2 shrink-0",
                      isPast || isActive
                        ? "bg-(--pp-accent-muted)"
                        : "bg-(--pp-border)"
                    )}
                    aria-hidden
                  />
                ) : null}
              </div>
            )
          })}
        </div>
      </div>
      <DotGridPanel dotGrid={zone.dotGrid} compact live={live} seed={`${instanceId}-signal`} />
    </MockScreen>
  )
}

function HealthSplitZone({
  zone,
  live,
}: {
  zone: Extract<MiniAppScreenZone, { type: "health-split" }>
  live: boolean
  pulseKey: number
}) {
  const chokeIndex = zone.areaPoints.reduce(
    (lowest, point, index) =>
      point < zone.areaPoints[lowest]! ? index : lowest,
    0
  )
  const chokeLeft =
    zone.areaPoints.length > 1
      ? `${(chokeIndex / (zone.areaPoints.length - 1)) * 100}%`
      : "50%"

  return (
    <MockScreen>
      <div className="flex min-h-0 flex-1">
        <div className="fsv8-health-sidebar flex w-[36%] shrink-0 flex-col border-r border-(--pp-border)">
          {zone.metrics.map((metric) => (
            <MetricCard
              key={metric.label}
              value={metric.value}
              label={metric.label}
              valueClassName={live ? "fsv8-stat-live" : undefined}
            />
          ))}
        </div>
        <div className="flex min-h-0 flex-1 flex-col px-2.5 py-2">
          <div className="mb-2 flex shrink-0 items-center justify-between gap-2">
            <span className="font-mono text-[0.5625rem] uppercase tracking-wider text-muted-foreground">
              {zone.chartLabel}
            </span>
            <span className="font-mono text-[0.5625rem] text-muted-foreground/80">
              Choke
            </span>
          </div>
          <div className="fsv8-area-chart-wrap relative min-h-0 flex-1">
            <MiniAreaChart points={zone.areaPoints} />
            <span
              className="fsv8-choke-mark pointer-events-none absolute bottom-1 top-1 w-px bg-(--pp-accent)/35"
              style={{ left: chokeLeft }}
              aria-hidden
            />
          </div>
        </div>
      </div>
    </MockScreen>
  )
}

function titleCase(value: string) {
  return value
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(" ")
}

function DataTableZone({
  zone,
  live,
  activeRowIndex,
}: {
  zone: Extract<MiniAppScreenZone, { type: "data-table" }>
  live: boolean
  pulseKey: number
  activeRowIndex: number
}) {
  return (
    <MockScreen>
      <div className="fsv8-table flex min-h-0 w-full flex-1 flex-col font-mono text-[0.625rem]">
        <div className="fsv8-table-head grid shrink-0 grid-cols-[minmax(0,1.4fr)_minmax(0,0.8fr)_minmax(0,0.9fr)] items-center gap-2 border-b border-(--pp-border) px-3 py-2 text-muted-foreground">
          {zone.columns.map((column) => (
            <span key={column.header} className="truncate">
              {titleCase(column.header)}
            </span>
          ))}
        </div>

        <div className="fsv8-table-rows flex min-h-0 flex-1 flex-col">
          {zone.rows.map((row, rowIndex) => {
            const isActive = live && rowIndex === activeRowIndex

            return (
              <div
                key={rowIndex}
                className={cn(
                  "fsv8-table-row grid min-h-0 flex-1 grid-cols-[minmax(0,1.4fr)_minmax(0,0.8fr)_minmax(0,0.9fr)] items-center gap-2 border-b border-(--pp-border) px-3 text-foreground/80 last:border-b-0",
                  isActive && "fsv8-table-row-live"
                )}
              >
                <span className="truncate text-foreground/90">
                  {titleCase(row.cells[0] ?? "")}
                </span>
                <span className="truncate text-muted-foreground">
                  {titleCase(row.cells[1] ?? "")}
                </span>
                <span
                  className={cn(
                    "truncate tabular-nums",
                    isActive ? "text-foreground" : "text-foreground/70"
                  )}
                >
                  {row.cells[2]}
                </span>
              </div>
            )
          })}
        </div>

        <div
          className="fsv8-table-foot shrink-0 border-t border-(--pp-border) px-3 py-2"
          aria-hidden
        >
          {"\u00A0"}
        </div>
      </div>
    </MockScreen>
  )
}

type LivePreviewProps = {
  live: boolean
  pulseKey: number
  activeNodeIndex: number
  activeRowIndex: number
  instanceId: string
}

function DashboardZone({
  zone,
  live,
  instanceId,
}: LivePreviewProps & {
  zone: Extract<MiniAppScreenZone, { type: "dashboard" }>
}) {
  return (
    <MockScreen>
      <div className="grid shrink-0 grid-cols-2 border-b border-(--pp-border)">
        {zone.metrics.map((metric) => (
          <MetricCard
            key={metric.label}
            value={metric.value}
            label={metric.label}
            valueClassName={live ? "fsv8-stat-live" : undefined}
          />
        ))}
      </div>
      {zone.bars ? (
        <MiniBarChart heights={zone.bars} live={live} seed={`${instanceId}-dash`} />
      ) : null}
      {zone.dotGrid ? (
        <DotGridPanel dotGrid={zone.dotGrid} live={live} seed={`${instanceId}-dash-dots`} />
      ) : null}
    </MockScreen>
  )
}

function ChartDashboardZone({
  zone,
  live,
  instanceId,
}: LivePreviewProps & {
  zone: Extract<MiniAppScreenZone, { type: "chart-dashboard" }>
}) {
  const { chart } = zone
  const values = chartValues(chart)

  return (
    <MockScreen>
      <div className="grid shrink-0 grid-cols-2 border-b border-(--pp-border)">
        {zone.metrics.map((metric) => (
          <MetricCard
            key={metric.label}
            value={metric.value}
            label={metric.label}
            valueClassName={live ? "fsv8-stat-live" : undefined}
          />
        ))}
      </div>
      {chart.type === "dots" && zone.dotGrid ? (
        <DotGridPanel dotGrid={zone.dotGrid} live={live} seed={`${instanceId}-chart-dots`} />
      ) : chart.type === "line" || chart.type === "sparkline" ? (
        <div
          className={cn(
            "fsv8-line-chart-wrap flex min-h-0 flex-1 px-3 py-3",
            live && "fsv8-area-chart-wrap-live"
          )}
          style={
            live
              ? ({
                  "--fsv8-scan-delay": `${elementDelay(`${instanceId}-line-scan`, 0, 4800)}ms`,
                } as CSSProperties)
              : undefined
          }
        >
          <MiniLineChart points={values} />
        </div>
      ) : chart.type === "area" ? (
        <div
          className={cn(
            "fsv8-area-chart-wrap flex min-h-0 flex-1 px-3 py-3",
            live && "fsv8-area-chart-wrap-live"
          )}
          style={
            live
              ? ({
                  "--fsv8-scan-delay": `${elementDelay(`${instanceId}-area-scan`, 0, 4800)}ms`,
                } as CSSProperties)
              : undefined
          }
        >
          <MiniAreaChart points={values} />
        </div>
      ) : (
        <MiniBarChart
          heights={values}
          thin={chart.barWidth === "thin"}
          live={live}
          seed={`${instanceId}-chart-bars`}
        />
      )}
    </MockScreen>
  )
}

function MiniAppScreen({
  zone,
  live,
  pulseKey,
  activeNodeIndex,
  activeRowIndex,
  instanceId,
}: { zone: MiniAppScreenZone } & LivePreviewProps) {
  const props = { live, pulseKey, activeNodeIndex, activeRowIndex, instanceId }

  if (zone.type === "live-stream") return <LiveStreamZone zone={zone} {...props} />
  if (zone.type === "signal-flow") return <SignalFlowZone zone={zone} {...props} />
  if (zone.type === "health-split") return <HealthSplitZone zone={zone} {...props} />
  if (zone.type === "data-table") return <DataTableZone zone={zone} {...props} />
  if (zone.type === "dashboard") return <DashboardZone zone={zone} {...props} />
  return <ChartDashboardZone zone={zone} {...props} />
}

export default function ProductPreviewFeature({
  spec,
  title,
  description,
  instanceId,
  live = false,
  className,
}: {
  spec: FeaturePreviewSpec
  title: string
  description: string
  instanceId: string
  live?: boolean
  className?: string
}) {
  const initialZone = spec.zones[0]
  const preview = useLiveFeaturePreview(initialZone, live, instanceId)

  return (
    <div
      className={cn(
        "fsv8-mock-frame relative flex h-full min-h-0 w-full min-w-0 flex-col overflow-hidden bg-(--pp-shell-bg)",
        className
      )}
      role="img"
      aria-label={`${title} — ${description}${live ? " — simulated live data" : ""}`}
    >
      {preview.zone ? (
        <MiniAppScreen
          zone={preview.zone}
          live={live}
          pulseKey={preview.pulseKey}
          activeNodeIndex={preview.activeNodeIndex}
          activeRowIndex={preview.activeRowIndex}
          instanceId={instanceId}
        />
      ) : null}
    </div>
  )
}

export type PreviewIntent =
  | "task"
  | "monitor"
  | "realtime"
  | "throughput"
  | "sync"

export type MiniTableColumn = { header: string }
export type MiniTableRow = { cells: ReadonlyArray<string> }

export type MiniChartZone = {
  type: "line" | "area" | "bars" | "dots" | "sparkline"
  heights?: ReadonlyArray<number>
  points?: ReadonlyArray<number>
  barWidth?: "thin" | "normal"
}

export type MiniAppScreenZone =
  | {
      type: "live-stream"
      panelTitle: string
      stats: ReadonlyArray<{ value: string; label: string }>
      bars: ReadonlyArray<number>
    }
  | {
      type: "signal-flow"
      panelTitle: string
      nodes: ReadonlyArray<{ label: string; volume: number }>
      dotGrid: ReadonlyArray<ReadonlyArray<boolean>>
    }
  | {
      type: "health-split"
      panelTitle: string
      metrics: ReadonlyArray<{ value: string; label: string }>
      chartLabel: string
      areaPoints: ReadonlyArray<number>
    }
  | {
      type: "data-table"
      variant: "table-compact" | "table-mono"
      panelTitle: string
      queueSummary: string
      columns: ReadonlyArray<MiniTableColumn>
      rows: ReadonlyArray<MiniTableRow>
    }
  | {
      type: "dashboard"
      variant: "dashboard-kpi" | "dashboard-split"
      panelTitle: string
      metrics: ReadonlyArray<{ value: string; label: string }>
      bars?: ReadonlyArray<number>
      dotGrid?: ReadonlyArray<ReadonlyArray<boolean>>
    }
  | {
      type: "chart-dashboard"
      variant: "chart-line" | "chart-area" | "chart-dots"
      panelTitle: string
      metrics: ReadonlyArray<{ value: string; label: string }>
      chart: MiniChartZone
      dotGrid?: ReadonlyArray<ReadonlyArray<boolean>>
    }

export type FeaturePreviewSpec = {
  intent: PreviewIntent
  zones: ReadonlyArray<MiniAppScreenZone>
}

export type BuildFeaturePreviewInput = {
  id: string
  title: string
  description: string
  size: "large" | "mini"
}

const INTENT_KEYWORDS: Record<PreviewIntent, ReadonlyArray<string>> = {
  task: [
    "task",
    "queue",
    "backlog",
    "scheduled",
    "track",
    "timestamp",
    "automation",
    "row",
    "owner",
  ],
  monitor: [
    "monitor",
    "health",
    "uptime",
    "pipeline",
    "depth",
    "bottleneck",
    "glance",
    "overview",
    "review",
  ],
  realtime: [
    "real-time",
    "realtime",
    "live",
    "instant",
    "latency",
    "execution",
    "performance",
    "streaming",
    "respond",
  ],
  throughput: [
    "volume",
    "throughput",
    "runs",
    "activity",
    "signals",
    "ingest",
    "coordinate",
    "route",
  ],
  sync: ["sync", "import", "export", "transform", "deliver"],
}

const INTENT_ROTATION: ReadonlyArray<PreviewIntent> = [
  "monitor",
  "throughput",
  "task",
  "realtime",
  "sync",
]

export function hashString(input: string): number {
  let hash = 0
  for (let index = 0; index < input.length; index += 1) {
    hash = (hash * 31 + input.charCodeAt(index)) >>> 0
  }
  return hash
}

function seededValue(seed: string, min: number, max: number): number {
  const span = max - min + 1
  return min + (hashString(seed) % span)
}

function seededFloats(seed: string, count: number): ReadonlyArray<number> {
  const values: number[] = []
  for (let index = 0; index < count; index += 1) {
    values.push(28 + (hashString(`${seed}-${index}`) % 72))
  }
  return values
}

function classifyIntent(id: string, title: string, description: string): PreviewIntent {
  const haystack = `${title} ${description}`.toLowerCase()
  let bestIntent: PreviewIntent = INTENT_ROTATION[hashString(id) % INTENT_ROTATION.length]
  let bestScore = 0

  for (const intent of INTENT_ROTATION) {
    const score = INTENT_KEYWORDS[intent].reduce(
      (total, keyword) => total + (haystack.includes(keyword) ? 1 : 0),
      0
    )
    if (score > bestScore) {
      bestScore = score
      bestIntent = intent
    }
  }

  return bestIntent
}

function splitClauses(description: string): string[] {
  return description
    .split(/[,;.]+/)
    .map((clause) => clause.trim())
    .filter(Boolean)
}

function titleWords(title: string): string[] {
  return title
    .toLowerCase()
    .split(/\s+/)
    .filter((word) => word.length > 2)
}

function panelTitleFromCopy(title: string, description: string): string {
  const clauses = splitClauses(description)
  if (clauses[0] && clauses[0].length <= 36) {
    return clauses[0].charAt(0).toUpperCase() + clauses[0].slice(1)
  }
  const words = title.split(/\s+/).slice(0, 3)
  return words.join(" ")
}

function metricLabelFromClause(clause: string, fallback: string): string {
  const trimmed = clause.trim()
  if (trimmed.length <= 22) return trimmed
  const words = trimmed.split(/\s+/).slice(-3)
  return words.join(" ")
}

function buildDotGrid(
  id: string,
  rows = 10,
  cols = 16
): ReadonlyArray<ReadonlyArray<boolean>> {
  return Array.from({ length: rows }, (_, row) =>
    Array.from(
      { length: cols },
      (_, col) => hashString(`${id}-dot-${row}-${col}`) % 3 !== 0
    )
  )
}

function buildTableZone(
  id: string,
  title: string,
  description: string,
  variant: "table-compact" | "table-mono"
): MiniAppScreenZone {
  const clauses = splitClauses(description)
  const panelTitle = panelTitleFromCopy(title, description)

  const columns: MiniTableColumn[] =
    variant === "table-mono"
      ? [{ header: "Handled" }, { header: "Assignee" }, { header: "Updated" }]
      : [{ header: "Item" }, { header: "Stage" }, { header: "Window" }]

  const rowSources = [
    clauses[0] ?? "Primary flow",
    clauses[1] ?? "Secondary path",
    clauses[2] ?? "Fallback lane",
    "Shared handoff",
  ]

  const rows: MiniTableRow[] = rowSources.slice(0, 4).map((clause, index) => {
    const words = clause.split(/\s+/).filter(Boolean)
    const cellA = words.slice(0, 2).join(" ") || `Lane ${index + 1}`
    const cellB = words.slice(2, 4).join(" ") || `Phase ${index + 1}`
    const cellC =
      variant === "table-mono"
        ? `${seededValue(`${id}-t-${index}`, 8, 23)}:${seededValue(`${id}-m-${index}`, 10, 59).toString().padStart(2, "0")}`
        : `${seededValue(`${id}-w-${index}`, 2, 9)}h window`

    return { cells: [cellA, cellB, cellC] }
  })

  return {
    type: "data-table",
    variant,
    panelTitle,
    queueSummary: `${rowSources.length} queued · next ${seededValue(`${id}-next-h`, 8, 23)}:${seededValue(`${id}-next-m`, 10, 59).toString().padStart(2, "0")}`,
    columns,
    rows,
  }
}

function buildDashboardZone(
  id: string,
  title: string,
  description: string,
  variant: "dashboard-kpi" | "dashboard-split"
): MiniAppScreenZone {
  const clauses = splitClauses(description)
  const panelTitle = panelTitleFromCopy(title, description)
  const words = titleWords(title)

  const metrics = [
    {
      value: `${seededValue(`${id}-m0`, 89, 99)}.${seededValue(`${id}-m0d`, 1, 9)}%`,
      label: metricLabelFromClause(clauses[0] ?? "Uptime trend", "Uptime trend"),
    },
    {
      value: `${seededValue(`${id}-m1`, 12, 148)}`,
      label: metricLabelFromClause(clauses[1] ?? words[0] ?? "Depth", "Queue depth"),
    },
  ]

  const bars = seededFloats(`${id}-bars`, 8)
  const dotGrid = buildDotGrid(id)

  return {
    type: "dashboard",
    variant,
    panelTitle,
    metrics,
    bars: variant === "dashboard-kpi" ? bars : undefined,
    dotGrid: variant === "dashboard-split" ? dotGrid : undefined,
  }
}

function buildChartZone(
  id: string,
  title: string,
  description: string,
  variant: "chart-line" | "chart-area" | "chart-dots"
): MiniAppScreenZone {
  const clauses = splitClauses(description)
  const panelTitle = panelTitleFromCopy(title, description)

  const chartTypes: ReadonlyArray<MiniChartZone["type"]> =
    variant === "chart-dots"
      ? ["dots"]
      : variant === "chart-area"
        ? ["area"]
        : ["line", "sparkline"]

  const chartType = chartTypes[hashString(`${id}-chart`) % chartTypes.length]
  const points = seededFloats(`${id}-pts`, 8)

  const metrics = [
    {
      value: `${seededValue(`${id}-r0`, 120, 890)}`,
      label: metricLabelFromClause(clauses[0] ?? "Active now", "Active now"),
    },
    {
      value: `${seededValue(`${id}-r1`, 1, 8)}.${seededValue(`${id}-r1d`, 1, 9)}s`,
      label: metricLabelFromClause(clauses[1] ?? "Avg delay", "Avg delay"),
    },
  ]

  return {
    type: "chart-dashboard",
    variant,
    panelTitle,
    metrics,
    chart: {
      type: chartType,
      points,
      heights: points,
    },
    dotGrid: chartType === "dots" ? buildDotGrid(`${id}-chart`) : undefined,
  }
}

type MiniVariant =
  | "table-compact"
  | "table-mono"
  | "dashboard-kpi"
  | "dashboard-split"
  | "chart-line"
  | "chart-area"
  | "chart-dots"

function pickMiniVariant(id: string, intent: PreviewIntent): MiniVariant {
  const variantsByIntent: Record<PreviewIntent, ReadonlyArray<MiniVariant>> = {
    task: ["table-compact", "table-mono"],
    monitor: ["dashboard-kpi", "dashboard-split"],
    realtime: ["chart-line", "chart-area", "chart-dots"],
    throughput: ["dashboard-split", "chart-dots", "chart-area"],
    sync: ["table-mono", "table-compact"],
  }

  const options = variantsByIntent[intent]
  return options[hashString(id) % options.length]
}

/** Fan-out activity — density increases left → right under the hop path. */
function buildFanOutDotGrid(
  id: string,
  rows = 8,
  cols = 14
): ReadonlyArray<ReadonlyArray<boolean>> {
  return Array.from({ length: rows }, (_, row) =>
    Array.from({ length: cols }, (_, col) => {
      const band = Math.floor((col / cols) * 3)
      const chance = band === 0 ? 2 : band === 1 ? 3 : 4
      return hashString(`${id}-fan-${row}-${col}`) % 5 < chance
    })
  )
}

/** Delivery curve with a mid-span choke dip. */
function seededDeliveryCurve(id: string, count = 10): number[] {
  return Array.from({ length: count }, (_, index) => {
    const base = seededValue(`${id}-del-${index}`, 58, 94)
    const choke = index === 4 || index === 5
    return choke ? Math.max(26, base - 38) : base
  })
}

/** Live run monitor — header stat strip + full-width latency histogram. */
function buildRealtimeExecutionZone(
  id: string,
  _title: string,
  _description: string
): MiniAppScreenZone {
  return {
    type: "live-stream",
    panelTitle: "Live runs",
    stats: [
      {
        value: `${seededValue(`${id}-r0`, 120, 890)}`,
        label: "Runs Firing",
      },
      {
        value: `${seededValue(`${id}-r1`, 1, 8)}.${seededValue(`${id}-r1d`, 1, 9)}s`,
        label: "Stage Delay",
