"use client"

import { useEffect, useRef, useState } from "react"

export function useInViewOnce(threshold = 0.35) {
  const ref = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState(false)

  useEffect(() => {
    const el = ref.current
    if (!el || active) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          setActive(true)
          observer.disconnect()
        }
      },
      { threshold }
    )

    observer.observe(el)
    return () => observer.disconnect()
  }, [active, threshold])

  return { ref, active }
}

"use client"

import { useEffect, useRef, useState, useSyncExternalStore } from "react"

import {
  jitterIntervalMs,
  tickInitialDelayMs,
  tickIntervalMs,
} from "../lib/animation-timing"
import type { MiniAppScreenZone } from "../lib/build-feature-preview"

function randomBarHeight(): number {
  return 28 + Math.floor(Math.random() * 72)
}

function jitterLiveStreamBar(
  zone: Extract<MiniAppScreenZone, { type: "live-stream" }>,
  barIndex: number
): Extract<MiniAppScreenZone, { type: "live-stream" }> {
  const bars = zone.bars.slice()
  bars[barIndex] = randomBarHeight()
  return { ...zone, bars }
}

function subscribeReducedMotion(onStoreChange: () => void) {
  const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
  mq.addEventListener("change", onStoreChange)
  return () => mq.removeEventListener("change", onStoreChange)
}

function getReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getReducedMotionServer() {
  return false
}

export type LiveFeaturePreview = {
  zone: MiniAppScreenZone
  pulseKey: number
  activeNodeIndex: number
  activeRowIndex: number
}

function tickBars(bars: ReadonlyArray<number>): number[] {
  const next = bars.slice(1)
  next.push(28 + Math.floor(Math.random() * 72))
  return next
}

function tickLiveStream(
  zone: Extract<MiniAppScreenZone, { type: "live-stream" }>
): Extract<MiniAppScreenZone, { type: "live-stream" }> {
  const runStat = zone.stats[0]
  const latencyStat = zone.stats[1]
  const runValue = Number.parseInt(runStat.value.replace(/\D/g, ""), 10) || 600
  const latencyValue = Number.parseFloat(latencyStat.value.replace(/[^\d.]/g, "")) || 2

  const nextLatency = Math.min(
    9.9,
    Math.max(1.0, latencyValue + (Math.random() - 0.5) * 0.35)
  )

  return {
    ...zone,
    stats: [
      {
        ...runStat,
        value: `${runValue + 4 + Math.floor(Math.random() * 14)}`,
      },
      {
        ...latencyStat,
        value: `${nextLatency.toFixed(1)}s`,
      },
    ],
    bars: tickBars(zone.bars),
  }
}

function tickSignalFlow(
  zone: Extract<MiniAppScreenZone, { type: "signal-flow" }>
): Extract<MiniAppScreenZone, { type: "signal-flow" }> {
  const nodes = zone.nodes.map((node, index) => {
    const floor = index === 0 ? 70 : index === 1 ? 30 : 12
    const ceiling = index === 0 ? 160 : index === 1 ? 110 : 70
    const next = Math.min(
      ceiling,
      Math.max(floor, node.volume + Math.floor(Math.random() * 11) - 4)
    )
    return { ...node, volume: next }
  })

  // Keep the hop path reading as fan-out: volumes stay descending.
  for (let index = 1; index < nodes.length; index += 1) {
    const prev = nodes[index - 1]
    const current = nodes[index]
    if (current.volume >= prev.volume) {
      nodes[index] = {
        ...current,
        volume: Math.max(6, prev.volume - (4 + Math.floor(Math.random() * 10))),
      }
    }
  }

  return {
    ...zone,
    nodes,
    dotGrid: zone.dotGrid.map((row) =>
      row.map((active, colIndex) => {
        const band = Math.floor((colIndex / row.length) * 3)
        const flipChance = band === 0 ? 0.88 : band === 1 ? 0.8 : 0.72
        return Math.random() > flipChance ? !active : active
      })
    ),
  }
}

function tickHealthSplit(
  zone: Extract<MiniAppScreenZone, { type: "health-split" }>
): Extract<MiniAppScreenZone, { type: "health-split" }> {
  const depthMetric = zone.metrics[0]
  const uptimeMetric = zone.metrics[1]
  const depth = Number.parseInt(depthMetric.value, 10) || 20
  const uptime = Number.parseFloat(uptimeMetric.value.replace(/[^\d.]/g, "")) || 97
  const nextUptime = Math.min(
    99.9,
    Math.max(95.0, uptime + (Math.random() > 0.55 ? -0.1 : 0.06))
  )

  const areaPoints = tickBars(zone.areaPoints).map((point, index) =>
    index === 4 || index === 5 ? Math.min(point, 42) : Math.max(point, 52)
  )

  return {
    ...zone,
    metrics: [
      {
        ...depthMetric,
        value: `${Math.max(6, depth + Math.floor(Math.random() * 5) - 2)}`,
      },
      {
        ...uptimeMetric,
        value: `${nextUptime.toFixed(1)}%`,
      },
    ],
    areaPoints,
  }
}

function tickQueueTime(time: string, stepMinutes = 1): string {
  const [hours, minutes] = time.split(":").map((part) => Number.parseInt(part, 10))
  if (Number.isNaN(hours) || Number.isNaN(minutes)) return time

  let total = hours * 60 + minutes + stepMinutes
  if (total >= 24 * 60) total -= 24 * 60

  const nextHours = Math.floor(total / 60)
  const nextMinutes = total % 60
  return `${nextHours}:${nextMinutes.toString().padStart(2, "0")}`
}

function tickDataTable(
  zone: Extract<MiniAppScreenZone, { type: "data-table" }>
): Extract<MiniAppScreenZone, { type: "data-table" }> {
  const rows = zone.rows.map((row) => {
    const updated = row.cells[2]
    if (!updated?.includes(":")) return row

    return {
      cells: [row.cells[0], row.cells[1], tickQueueTime(updated)] as [
        string,
        string,
        string,
      ],
    }
  })

  const nextSummary = zone.queueSummary.replace(/next (\d+:\d+)/, (_, time) => {
    return `next ${tickQueueTime(time)}`
  })

  return {
    ...zone,
    queueSummary: nextSummary,
    rows,
  }
}

function tickZone(zone: MiniAppScreenZone): MiniAppScreenZone {
  switch (zone.type) {
    case "live-stream":
      return tickLiveStream(zone)
    case "signal-flow":
      return tickSignalFlow(zone)
    case "health-split":
      return tickHealthSplit(zone)
    case "data-table":
      return tickDataTable(zone)
    case "dashboard":
      return {
        ...zone,
        bars: zone.bars ? tickBars(zone.bars) : undefined,
        dotGrid: zone.dotGrid
          ? zone.dotGrid.map((row) =>
              row.map((active) => (Math.random() > 0.8 ? !active : active))
            )
          : undefined,
      }
    case "chart-dashboard":
      return {
        ...zone,
        chart: {
          ...zone.chart,
          heights: zone.chart.heights ? tickBars(zone.chart.heights) : zone.chart.heights,
          points: zone.chart.points ? tickBars(zone.chart.points) : zone.chart.points,
        },
        dotGrid: zone.dotGrid
          ? zone.dotGrid.map((row) =>
              row.map((active) => (Math.random() > 0.8 ? !active : active))
            )
          : undefined,
      }
    default:
      return zone
  }
}

function createInitialPreview(zone: MiniAppScreenZone): LiveFeaturePreview {
  return {
    zone,
    pulseKey: 0,
    activeNodeIndex: 0,
    activeRowIndex: 0,
  }
}

export function useLiveFeaturePreview(
  initialZone: MiniAppScreenZone,
  enabled: boolean,
  instanceId: string
): LiveFeaturePreview {
  const reducedMotion = useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    getReducedMotionServer
  )

  const isLive = enabled && !reducedMotion

  const zoneRef = useRef(initialZone)
  const pulseRef = useRef(0)
  const nodeRef = useRef(0)
  const rowRef = useRef(0)

  const [preview, setPreview] = useState<LiveFeaturePreview>(() =>
    createInitialPreview(initialZone)
  )

  useEffect(() => {
    if (!isLive) {
      return
    }

    zoneRef.current = initialZone
    pulseRef.current = 0
    nodeRef.current = 0
    rowRef.current = 0

    let cancelled = false
    queueMicrotask(() => {
      if (!cancelled) {
        setPreview(createInitialPreview(initialZone))
      }
    })

    const tickMs = tickIntervalMs(instanceId)
    const initialDelay = tickInitialDelayMs(instanceId)

    const runTick = () => {
      zoneRef.current = tickZone(zoneRef.current)
      pulseRef.current += 1
      nodeRef.current = (nodeRef.current + 1) % 3
      rowRef.current =
        zoneRef.current.type === "data-table"
          ? (rowRef.current + 1) % zoneRef.current.rows.length
          : 0

      setPreview({
        zone: zoneRef.current,
        pulseKey: pulseRef.current,
        activeNodeIndex: nodeRef.current,
        activeRowIndex: rowRef.current,
      })
    }

    let intervalId: number | undefined
    const startTimeout = window.setTimeout(() => {
      runTick()
      intervalId = window.setInterval(runTick, tickMs)
    }, initialDelay)

    return () => {
      cancelled = true
      window.clearTimeout(startTimeout)
      if (intervalId !== undefined) window.clearInterval(intervalId)
    }
  }, [isLive, initialZone, instanceId])

  useEffect(() => {
    if (!isLive || initialZone.type !== "live-stream") {
      return
    }

    const jitterMs = jitterIntervalMs(instanceId)

    const jitterInterval = window.setInterval(() => {
      const zone = zoneRef.current
      if (zone.type !== "live-stream" || zone.bars.length === 0) return

      const updates = 1 + (Math.random() > 0.55 ? 1 : 0)
      let nextZone = zone

      for (let count = 0; count < updates; count += 1) {
        const barIndex = Math.floor(Math.random() * nextZone.bars.length)
        nextZone = jitterLiveStreamBar(nextZone, barIndex)
      }

      zoneRef.current = nextZone
      setPreview((current) => ({ ...current, zone: nextZone }))
    }, jitterMs)

    return () => window.clearInterval(jitterInterval)
  }, [isLive, initialZone.type, instanceId])

  if (!isLive) {
    return createInitialPreview(initialZone)
  }

  return preview
}

.fsv8-mock-frame {
  --pp-shell-bg: oklch(0.985 0 0);
  --pp-border: rgb(0 0 0 / 0.1);
  --pp-accent: rgb(39 39 42);
  --pp-accent-muted: rgb(39 39 42 / 0.28);
  --pp-accent-soft: rgb(39 39 42 / 0.06);
  --pp-accent-row: rgb(39 39 42 / 0.04);
  --pp-dot-idle: rgb(161 161 170 / 0.35);
  border: 1px solid var(--border);
}

.dark .fsv8-mock-frame {
  --pp-shell-bg: oklch(0.12 0 0);
  --pp-border: rgb(255 255 255 / 0.1);
  --pp-accent: rgb(228 228 231);
  --pp-accent-muted: rgb(228 228 231 / 0.28);
  --pp-accent-soft: rgb(228 228 231 / 0.08);
  --pp-accent-row: rgb(228 228 231 / 0.06);
  --pp-dot-idle: rgb(242 242 242 / 0.35);
}

.fsv8-dot-pattern {
  background-image: radial-gradient(
    circle at center,
    color-mix(in oklab, var(--foreground) 12%, transparent) 1px,
    transparent 1px
  );
  background-size: 18px 18px;
  background-position: 12px 12px;
}

.fsv8-dot-grid {
  flex: 1;
  display: grid;
  width: 100%;
  min-height: 0;
  height: 100%;
  padding: 0.5rem 0.625rem 0.625rem;
  gap: 0;
}

.fsv8-dot-grid--compact {
  padding: 0.375rem 0.625rem 0.5rem;
}

.fsv8-dot-grid-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
}

.fsv8-dot-grid-dot {
  width: clamp(3px, 42%, 7px);
  height: clamp(3px, 42%, 7px);
  border-radius: 9999px;
  background: var(--pp-dot-idle);
}

.fsv8-dot-grid-dot--active {
  background: var(--pp-accent);
}

.fsv8-mock-screen {
  height: 100%;
  min-height: 0;
}

.fsv8-mock-body {
  flex: 1;
  min-height: 0;
}

.fsv8-mock-frame:has(.fsv8-table) {
  height: 100%;
  min-height: 100%;
}

.fsv8-mock-frame:has(.fsv8-table) .fsv8-mock-screen {
  flex: 1;
  height: 100%;
  min-height: 10.25rem;
}

.fsv8-metric {
  border-right: 1px solid var(--pp-border);
}

.fsv8-metric:nth-child(2n) {
  border-right: none;
}

.fsv8-stat-strip-item:not(:last-child) {
  border-right: 1px solid var(--pp-border);
}

.fsv8-health-sidebar .fsv8-metric {
  flex: 1;
  border-right: none;
  border-bottom: 1px solid var(--pp-border);
}

.fsv8-health-sidebar .fsv8-metric:last-child {
  border-bottom: none;
}

.fsv8-sparkline-wrap {
  height: 2.75rem;
}

.fsv8-signal-hop {
  background: var(--pp-border);
}

.fsv8-signal-hop--past {
  background: var(--pp-accent-muted);
}

.fsv8-signal-hop--active {
  background: var(--pp-accent);
}

.fsv8-bar-chart {
  min-height: 0;
}

.fsv8-bar-chart--thin {
  gap: 2px;
}

.fsv8-bar {
  transform-origin: bottom;
  transition:
    height var(--fsv8-bar-duration, 700ms) cubic-bezier(0.4, 0, 0.2, 1)
      var(--fsv8-bar-delay, 0ms),
    background-color 500ms ease var(--fsv8-bar-delay, 0ms);
}

.fsv8-bar-live {
  animation: fsv8-bar-rise var(--fsv8-bar-rise-duration, 700ms)
    cubic-bezier(0.4, 0, 0.2, 1) var(--fsv8-bar-rise-delay, 0ms) backwards;
}

.fsv8-bar-chart-live {
  position: relative;
  overflow: hidden;
}

.fsv8-bar-chart-live::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--pp-accent-soft) 50%,
    transparent 100%
  );
  transform: translateX(-100%);
  animation: fsv8-chart-scan 5s ease-in-out var(--fsv8-scan-delay, 0ms) infinite;
}
.fsv8-dot-grid-live .fsv8-dot-grid-dot--live {
  animation: fsv8-dot-pulse var(--fsv8-dot-duration, 1.8s) ease-in-out
    var(--fsv8-dot-delay, 0ms) infinite;
}

.fsv8-area-chart-wrap-live {
  position: relative;
  overflow: hidden;
}

.fsv8-area-chart-wrap-live::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--pp-accent-soft) 50%,
    transparent 100%
  );
  transform: translateX(-100%);
  animation: fsv8-chart-scan 5s ease-in-out var(--fsv8-scan-delay, 0ms) infinite;
}

.fsv8-stat-live {
  animation: fsv8-stat-tick var(--fsv8-stat-duration, 650ms) ease
    var(--fsv8-stat-delay, 0ms);
}

.fsv8-table-row-live {
  background: var(--pp-accent-row);
  transition: background-color 450ms ease;
}

@keyframes fsv8-bar-rise {
  from {
    transform: scaleY(0.15);
    opacity: 0.35;
  }

  to {
    transform: scaleY(1);
    opacity: 1;
  }
}

@keyframes fsv8-chart-scan {
  0%,
  100% {
    transform: translateX(-100%);
    opacity: 0;
  }

  12% {
    opacity: 1;
  }

  45% {
    transform: translateX(100%);
    opacity: 1;
  }

  55% {
    opacity: 0;
  }
}

@keyframes fsv8-stat-tick {
  0% {
    opacity: 0.55;
    transform: translateY(2px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fsv8-dot-pulse {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.85);
  }

  50% {
    opacity: 1;
    transform: scale(1);
  }
}

.fsv8-bar--thin {
  width: 4px;
  min-height: 2px;
}

.fsv8-line-chart-wrap,
.fsv8-area-chart-wrap {
  min-height: 0;
}

.fsv8-line-chart,
.fsv8-area-chart {
  overflow: visible;
}

@media (prefers-reduced-motion: reduce) {
  .fsv8-bar-live,
  .fsv8-bar-chart-live::after,
  .fsv8-area-chart-wrap-live::after,
  .fsv8-stat-live,
  .fsv8-dot-grid-dot--live,
  .fsv8-table-row-live {
    animation: none;
    transition: none;
  }
}

import { hashString } from "./build-feature-preview"

export function elementDelay(seed: string, min = 0, max = 900): number {
  const span = max - min + 1
  return min + (hashString(seed) % span)
}

export function elementDuration(seed: string, min = 450, max = 1300): number {
  const span = max - min + 1
  return min + (hashString(seed) % span)
}

export function tickIntervalMs(instanceId: string, base = 2400, spread = 1000): number {
  const offset = (hashString(`${instanceId}-tick`) % spread) - spread / 2
  return Math.round(base + offset)
}

export function tickInitialDelayMs(instanceId: string, max = 2800): number {
  return hashString(`${instanceId}-init`) % max
}

export function jitterIntervalMs(instanceId: string, min = 110, max = 320): number {
  const span = max - min + 1
  return min + (hashString(`${instanceId}-jitter`) % span)
}

